@csrf_exempt
def api_courses(request):
    if request.method != "GET":
        return JsonResponse({"error": "Method not allowed."}, status=405)
    user, error = _api_user_from_request(request)
    if error:
        return error
    rows = [
        {
            "id": course.id,
            "code": course.code,
            "title": course.title,
            "status": course.status,
            "enrollment_mode": course.enrollment_mode,
        }
        for course in visible_courses(user).filter(status__in=[Course.Status.PUBLISHED, Course.Status.DRAFT, Course.Status.ARCHIVED])
    ]
    return JsonResponse({"courses": rows})

@csrf_exempt
def api_submissions(request):
    if request.method != "GET":
        return JsonResponse({"error": "Method not allowed."}, status=405)
    user, error = _api_user_from_request(request)
    if error:
        return error
    rows = []
    for submission in visible_submissions(user).select_related("assignment", "assignment__course", "student")[:500]:
        item = {
            "id": submission.id,
            "course": submission.assignment.course.code,
            "assignment": submission.assignment.title,
            "student": submission.student.username if not is_student(user) else user.username,
            "status": submission.status,
            "submitted_at": submission.submitted_at.isoformat() if submission.submitted_at else None,
        }
        if is_student(user):
            item["released_grade"] = format_grade(submission.released_grade) if submission.status == Submission.Status.RELEASED else None
        else:
            item["draft_grade"] = format_grade(submission.draft_grade)
            item["released_grade"] = format_grade(submission.released_grade)
        rows.append(item)
    return JsonResponse({"submissions": rows})

